package net.civeira.phylax.feature.oauth.client.application.usecase.readdynamicclient;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.client.application.usecase.registerclient.RegisterClientUsecase;
import net.civeira.phylax.feature.oauth.client.domain.DynamicClientData;
import net.civeira.phylax.feature.oauth.client.domain.exception.DynamicClientException;
import net.civeira.phylax.feature.oauth.client.domain.gateway.DynamicClientGateway;

/**
 * Reads the configuration of a dynamically registered client (RFC 7592 §2.1, task 2.1).
 *
 * <p>
 * Only from the tenant that owns the client and with its registration access token. The secret is
 * never returned again (task 2.8): it is stored as a digest.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ReadDynamicClientUsecase {

  private final DynamicClientGateway gateway;

  /**
   * Reads a client.
   *
   * @param tenant tenant name of the endpoint
   * @param issuer issuer of the tenant
   * @param clientId client identifier
   * @param registrationAccessToken token presented in clear
   * @return the metadata
   * @throws DynamicClientException invalid_token when the client or token does not match
   */
  public DynamicClientData read(String tenant, String issuer, String clientId,
      String registrationAccessToken) {
    return gateway.find(tenant, clientId, registrationAccessToken)
        .map(
            data -> data.toBuilder()
                .registrationClientUri(
                    RegisterClientUsecase.registrationClientUri(issuer, clientId))
                .build())
        .orElseThrow(DynamicClientException::invalidRegistrationToken);
  }
}
